func TestZZFuzzRouter(t *testing.T) {
	rng := rand.New(rand.NewSource(42))
	for iter := 0; iter < 3000; iter++ {
		e := New()
		r := e.router
		n := 1 + rng.Intn(4)
		added := map[string]bool{}
		for i := 0; i < n; i++ {
			p := routePool[rng.Intn(len(routePool))]
			if added[p] {
				continue
			}
			added[p] = true
			r.Add(http.MethodGet, p, handlerFunc)
		}
		for _, path := range pathPool {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Fatalf("PANIC routes=%v path=%q: %v", added, path, rec)
					}
				}()
				done := make(chan struct{})
				go func() {
					defer func() {
						if rec := recover(); rec != nil {
							fmt.Println("panic in goroutine", rec)
						}
						close(done)
					}()
					c := e.NewContext(nil, nil).(*context)
					r.Find(http.MethodGet, path, c)
				}()
				select {
				case <-done:
				case <-time.After(2 * time.Second):
					t.Fatalf("LOOP routes=%v path=%q", added, path)
				}
			}()
		}
	}
}
