package echo

import (
	"fmt"
	"net/http"
	"sort"
	"strings"
	"testing"
)

// ---------- reference matcher ----------

const (
	refStatic = 0
	refParam  = 1
	refAny    = 2
)

type refTok struct {
	kind int
	val  string
}

func refParse(route string) []refTok {
	var out []refTok
	i := 0
	for i < len(route) {
		switch route[i] {
		case ':':
			out = append(out, refTok{refParam, ""})
			i++
			for i < len(route) && route[i] != '/' {
				i++
			}
		case '*':
			out = append(out, refTok{refAny, ""})
			i++
		default:
			j := i
			for j < len(route) && route[j] != ':' && route[j] != '*' {
				j++
			}
			out = append(out, refTok{refStatic, route[i:j]})
			i = j
		}
	}
	return out
}

// refMatch returns whether route matches path (echo documented semantics) and the
// param values in order.
func refMatch(route, path string) (bool, []string) {
	toks := refParse(route)
	params := []string{}
	var dfs func(ti, pi int) bool
	dfs = func(ti, pi int) bool {
		if ti == len(toks) {
			return pi == len(path)
		}
		t := toks[ti]
		switch t.kind {
		case refStatic:
			if strings.HasPrefix(path[pi:], t.val) && dfs(ti+1, pi+len(t.val)) {
				return true
			}
			return false
		case refParam:
			if pi >= len(path) {
				return false
			}
			j := pi
			for j < len(path) && path[j] != '/' {
				j++
			}
			params = append(params, path[pi:j])
			if dfs(ti+1, j) {
				return true
			}
			params = params[:len(params)-1]
			return false
		case refAny:
			params = append(params, path[pi:])
			return true
		}
		return false
	}
	if dfs(0, 0) {
		return true, params
	}
	return false, nil
}

// refFind returns the route path matched by the reference matcher for the given
// route set (priority: static > param > any at each step, with backtracking;
// ties between equally specific routes resolved by longest match / first in
// sorted order for determinism).
func refFind(routes []string, path string) (string, []string, bool) {
	type hit struct {
		route  string
		params []string
	}
	var hits []hit
	for _, r := range routes {
		if ok, p := refMatch(r, path); ok {
			hits = append(hits, hit{r, p})
		}
	}
	if len(hits) == 0 {
		return "", nil, false
	}
	// Deterministic pick: prefer the one with most static characters matched,
	// then lexicographically smallest route.
	best := hits[0]
	for _, h := range hits[1:] {
		if len(h.route) > len(best.route) {
			best = h
		}
	}
	return best.route, best.params, true
}

// ---------- differential test ----------

var refRoutePool = []string{
	"/", "/a", "/a/b", "/a/b/c", "/a/:p", "/a/:p/c", "/:p", "/:p/b", "/:p/:q",
	"/*", "/a/*", "/a/b/*", "/x/y", "/x/:p", "/x/*", "/a/b/:p", "/a/:p/:q",
	"/ab", "/abc", "/a/bc", "/a/bcd",
}

var refPathPool = []string{
	"/", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/b/c/d", "/x", "/x/",
	"/x/y", "/x/y/z", "/ab", "/abc", "/abcd", "/a/bc", "/a/bcd", "/a/x",
	"/a/x/c", "/a/x/y", "/a/b/c/d/e", "/q", "/q/r",
}

func realFind(t *testing.T, routes []string, path string) (string, []string, bool, interface{}) {
	t.Helper()
	e := New()
	r := e.router
	for _, rt := range routes {
		r.Add(http.MethodGet, rt, func(c Context) error {
			c.Set("path", c.Path())
			return nil
		})
	}
	c := e.NewContext(nil, nil).(*context)
	r.Find(http.MethodGet, path, c)
	if c.handler == nil {
		return "", nil, false, nil
	}
	// run handler to record path
	_ = c.handler(c)
	if c.handler == NotFoundHandler {
		return "", nil, false, "NotFound"
	}
	p := c.Get("path")
	if p == nil {
		return "", nil, false, fmt.Sprintf("handler=%p", c.handler)
	}
	params := append([]string{}, c.pvalues[:len(c.pnames)]...)
	return p.(string), params, true, nil
}

func TestZZDiffRouter(t *testing.T) {
	combos := [][]string{}
	var gen func(start int, cur []string)
	gen = func(start int, cur []string) {
		if len(cur) >= 1 {
			c := append([]string{}, cur...)
			combos = append(combos, c)
		}
		if len(cur) == 4 {
			return
		}
		for i := start; i < len(refRoutePool); i++ {
			gen(i+1, append(cur, refRoutePool[i]))
		}
	}
	gen(0, nil)
	t.Logf("combos: %d", len(combos))

	mismatches := 0
	for _, routes := range combos {
		sorted := append([]string{}, routes...)
		sort.Strings(sorted)
		for _, path := range refPathPool {
			expRoute, expParams, expOK := refFind(routes, path)
			gotRoute, gotParams, gotOK, note := func() (gr string, gp []string, gok bool, n interface{}) {
				defer func() {
					if rec := recover(); rec != nil {
						gr, gp, gok, n = "", nil, false, fmt.Sprintf("PANIC %v", rec)
					}
				}()
				return realFind(t, routes, path)
			}()
			if expOK != gotOK || (expOK && (expRoute != gotRoute || strings.Join(expParams, "|") != strings.Join(gotParams, "|"))) {
				mismatches++
				if mismatches <= 60 {
					t.Errorf("routes=%v path=%q ref=(%v,%v,%v) got=(%v,%v,%v) note=%v",
						routes, path, expOK, expRoute, expParams, gotOK, gotRoute, gotParams, note)
				}
			}
		}
	}
	t.Logf("total mismatches: %d", mismatches)
}

// refFind returns all routes from the set that match path, plus their params.
func refFind(routes []string, path string) map[string][]string {
	hits := map[string][]string{}
	for _, r := range routes {
		if ok, p := refMatch(r, path); ok {
			hits[r] = p
		}
	}
	return hits
}

