package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"reflect"
	"strings"
	"testing"
)

// ---------- reference matcher ----------

const (
	refStatic = 0
	refParam  = 1
	refAny    = 2
)

type refTok struct {
	kind int
	val  string
}

func refParse(route string) []refTok {
	var out []refTok
	i := 0
	for i < len(route) {
		switch route[i] {
		case ':':
			out = append(out, refTok{refParam, ""})
			i++
			for i < len(route) && route[i] != '/' {
				i++
			}
		case '*':
			out = append(out, refTok{refAny, ""})
			i++
		default:
			j := i
			for j < len(route) && route[j] != ':' && route[j] != '*' {
				j++
			}
			out = append(out, refTok{refStatic, route[i:j]})
			i = j
		}
	}
	return out
}

// refMatch returns whether route matches path (echo documented semantics) and the
// param values in order.
func refMatch(route, path string) (bool, []string) {
	toks := refParse(route)
	params := []string{}
	var dfs func(ti, pi int) bool
	dfs = func(ti, pi int) bool {
		if ti == len(toks) {
			return pi == len(path)
		}
		t := toks[ti]
		switch t.kind {
		case refStatic:
			if strings.HasPrefix(path[pi:], t.val) && dfs(ti+1, pi+len(t.val)) {
				return true
			}
			return false
		case refParam:
			if pi >= len(path) {
				return false
			}
			j := pi
			for j < len(path) && path[j] != '/' {
