// ---------- random fuzz against reference ----------

func randRoute(rng *rand.Rand) string {
	// build a path with 1-4 segments; last segment may be ":" or "*"
	n := 1 + rng.Intn(4)
	segs := make([]string, 0, n)
	for i := 0; i < n; i++ {
		switch rng.Intn(3) {
		case 0:
			segs = append(segs, string(rune('a'+rng.Intn(3))))
		case 1:
			segs = append(segs, string(rune('a'+rng.Intn(3)))+string(rune('a'+rng.Intn(3))))
		case 2:
			segs = append(segs, string(rune('a'+rng.Intn(3))))
		}
	}
	if rng.Intn(3) == 0 {
		segs[n-1] = ":p" + fmt.Sprint(rng.Intn(3))
	}
	if rng.Intn(4) == 0 {
		segs[n-1] = "*"
	}
	return "/" + strings.Join(segs, "/")
}

func randPath(rng *rand.Rand) string {
	n := 1 + rng.Intn(4)
	segs := make([]string, 0, n)
	for i := 0; i < n; i++ {
		segs = append(segs, string(rune('a'+rng.Intn(3)))+string(rune('a'+rng.Intn(3))))
	}
	return "/" + strings.Join(segs, "/")
}

